3	namespace App\Jobs\Shopify;
4	
5	use App\Models\Core\Professional\Professional;
6	use App\Models\Core\Professional\ProfessionalIntegration;
7	use App\Models\Core\Site\Site;
8	use App\Services\Shopify\ShopProfileAutoFillService;
9	use Illuminate\Bus\Queueable;
10	use Illuminate\Contracts\Queue\ShouldQueue;
11	use Illuminate\Foundation\Bus\Dispatchable;
12	use Illuminate\Queue\InteractsWithQueue;
13	use Illuminate\Queue\SerializesModels;
14	use Illuminate\Support\Facades\Cache;
15	use Illuminate\Support\Facades\Log;
16	
17	// Processes shop/update webhooks — re-syncs brand profile fields (honouring any
18	// shopify_sync_locked_fields the brand has set) and triggers a throttled brand-design
19	// refresh (logos, colours, enums, slogan).
20	class ProcessShopifyShopUpdateJob implements ShouldQueue
21	{
22	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
23	
24	    public int $tries = 3;
25	
26	    public int $timeout = 30;
27	
28	    public function __construct(
29	        public string $professionalId,
30	        public array $payload,
31	    ) {
32	        $this->onQueue('integrations');
33	    }
34	
35	    public function handle(): void
36	    {
37	        $professional = Professional::find($this->professionalId);
38	
39	        if (! $professional) {
40	            return;
41	        }
42	
43	        $site = Site::where('professional_id', $this->professionalId)->first();
44	
45	        if (! $site) {
46	            return;
47	        }
48	
49	        $integration = ProfessionalIntegration::query()
50	            ->where('professional_id', $this->professionalId)
51	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
52	            ->first();
53	
54	        if (! $integration) {
55	            Log::warning('Shopify shop/update: no integration record found.', [
56	                'professional_id' => $this->professionalId,
57	            ]);
58	
59	            return;
60	        }
61	
62	        // Re-sync profile fields, honouring shopify_sync_locked_fields for brands
63	        // that have customized specific fields locally.
64	        app(ShopProfileAutoFillService::class)->resyncFromShopData(
65	            $integration,
66	            $this->payload,
67	        );
68	
69	        // Re-sync the full brand-design shape (logos, colours, enums, slogan).
70	        // Throttled to once per hour per integration so a chatty shop/update
71	        // webhook stream can't pummel Shopify with brand-design fetches.
72	        $cacheKey = "shopify:brand_design_sync:{$integration->id}";
73	        if (Cache::add($cacheKey, true, now()->addHour())) {
74	            SyncShopifyBrandDesignJob::dispatch((string) $integration->id);
75	        }
76	
77	        Log::info('Shopify shop/update processed.', [
78	            'professional_id' => $this->professionalId,
79	            'shop_name' => $this->payload['name'] ?? null,
80	        ]);
81	    }
82	}
