11	
12	// V2: Dispatches affiliate notification fan-out when brand_status changes to live,
13	// building, or systems_down (meaningful affiliate-facing transitions).
14	class BrandProfileObserver
15	{
16	    public bool $afterCommit = true;
17	
18	    public function updated(BrandProfile $brandProfile): void
19	    {
20	        try {
21	            if (! $brandProfile->isDirty('brand_status')) {
22	                return;
23	            }
24	
25	            $brandProfessionalId = trim((string) ($brandProfile->professional_id ?? ''));
26	            if ($brandProfessionalId === '') {
27	                return;
28	            }
29	
30	            // Bust the per-affiliate brand-partner-status cache (CACHE-5). The
31	            // /api/me dashboard displays the linked brand's status banner from
32	            // this cache; without busting, every affiliate connected to this
33	            // brand would see the old status for up to 5 minutes.
34	            try {
35	                Cache::forget(CacheKeyGenerator::brandPartnerStatus($brandProfessionalId));
36	            } catch (\Throwable $e) {
37	                Log::warning('brand-partner-status cache invalidation failed', [
38	                    'brand_professional_id' => $brandProfessionalId,
39	                    'message' => $e->getMessage(),
40	                ]);
41	            }
42	
43	            $newStatus = $brandProfile->brand_status;
44	            // Only fan out on transitions affiliates care about:
45	            //   live          → brand program is now active
46	            //   building      → brand program was paused/reset
47	            //   systems_down  → platform-level outage
48	            // preview is an internal wizard state — affiliates don't need a notification.
49	            if (! in_array($newStatus, [BrandStatus::ReadyForAffiliates->value, BrandStatus::Onboarding->value, BrandStatus::SystemsDown->value], true)) {
50	                return;
51	            }
52	
53	            FanOutBrandStatusNotificationJob::dispatch($brandProfessionalId, $newStatus);
54	        } catch (\Throwable $e) {
55	            Log::warning('BrandProfile updated notification dispatch failed', [
56	                'brand_profile_id' => $brandProfile->id,
57	                'message' => $e->getMessage(),
58	            ]);
59	        }
60	    }
61	}
