17	/**
18	 * Single source of truth for brand lifecycle status.
19	 *
20	 * Evaluates status by composing existing data (wizard progress, storefront
21	 * reachability, onboarding readiness) without duplicating any check logic.
22	 * Called from controllers after every mutation that could change status.
23	 *
24	 * Stages 1-5 are progressive — brands step through in order:
25	 *   1. onboarding           — fresh signup, no Shopify connection
26	 *   2. shopify_linked       — OAuth complete, access_token present
27	 *   3. shopify_configured   — Hydrogen/Oxygen/Domain configured
28	 *   4. storefront_live      — storefront HTTP-reachable
29	 *   5. ready_for_affiliates — full live gate (images + Shopify + Stripe)
30	 *
31	 * Out-of-band: disconnected (app uninstalled), systems_down (manual override).
32	 * systems_down now auto-recovers when gates pass at storefront_live or above.
33	 */
34	class BrandStatusService
35	{
36	    // Per-instance memoization. determine() / sync() call hasShopifyConnected()
37	    // up to 3× per evaluation (lines 66, 206 via isWizardComplete, 258 via
38	    // isOnboardingReady) — cache it so we hit the DB once per professional
39	    // per service-instance lifetime (instance is request-scoped via app()).
40	    /** @var array<string, bool> */
41	    private array $shopifyConnectedCache = [];
42	
43	    /**
44	     * Determine the brand status for a professional without writing to DB.
45	     */
46	    public function determine(Professional $professional): BrandStatus
47	    {
48	        $brandProfile = BrandProfile::where('professional_id', $professional->id)->first();
49	        $integrationCheck = $this->integrationState($professional->id);
50	
51	        // ── Disconnected: app uninstalled, token nulled, integration row kept ──
52	        if ($integrationCheck['has_disconnected_at']) {
53	            return BrandStatus::Disconnected;
54	        }
55	
56	        // Integration row exists but no access_token (embedded connect-code without OAuth yet,
57	        // or app/uninstalled webhook which sets disconnected_at — caught above)
58	        if ($integrationCheck['has_integration'] && ! $integrationCheck['has_token']) {
59	            return BrandStatus::Disconnected;
60	        }
61	
62	        // ── No integration at all → fresh signup ──
63	        if (! $integrationCheck['has_integration']) {
64	            return BrandStatus::Onboarding;
65	        }
66	
67	        // ── Shopify linked at minimum (integration exists + access_token) ──
68	        $storeSettings = BrandStoreSettings::where('professional_id', $professional->id)->first();
69	        $site = Site::where('professional_id', $professional->id)->first();
70	        $subdomain = $site?->subdomain ?? '';
71	
72	        // Shopify-connected brands bypass Hydrogen/Oxygen wizard gate.
73	        // They can use affiliate marketing without deploying a storefront.
74	        $hasShopifyConnected = $this->hasShopifyConnected($professional->id);
75	
76	        // Wizard gate: all steps complete OR Shopify-connected bypass
77	        $wizardComplete = $hasShopifyConnected || $this->isWizardComplete($storeSettings, $subdomain, $professional->id);
78	
79	        if (! $wizardComplete) {
80	            return BrandStatus::ShopifyLinked;
81	        }
82	
83	        // ── Wizard complete. Check storefront reachability ──
84	        $storefrontReachable = $hasShopifyConnected || $this->isStorefrontReachable($storeSettings, $subdomain);
85	
86	        if (! $storefrontReachable) {
87	            return BrandStatus::ShopifyConfigured;
88	        }
89	
90	        // ── Storefront reachable. Check affiliate readiness ──
91	        $onboardingReady = $this->isOnboardingReady($professional, $site);
92	
93	        if (! $onboardingReady) {
94	            return BrandStatus::StorefrontLive;
95	        }
96	
97	        return BrandStatus::ReadyForAffiliates;
98	    }
99	
100	    /**
101	     * Evaluate and persist the current brand status.
102	     * Returns the new status if it changed, null if unchanged.
103	     * systems_down auto-recovers when computed status reaches storefront_live or above.
104	     */
105	    public function sync(Professional $professional): ?string
106	    {
107	        $computed = $this->determine($professional);
108	
109	        $existing = BrandProfile::where('professional_id', $professional->id)
110	            ->first();
111	
112	        $currentStatusValue = $existing?->brand_status ?? 'onboarding';
113	
114	        // Auto-recovery from systems_down: allow transition out when computed
115	        // status is storefront_live or above (platform issue resolved).
116	        if ($currentStatusValue === BrandStatus::SystemsDown->value) {
117	            if ($computed->isAtLeast(BrandStatus::StorefrontLive)) {
118	                // Allow recovery — fall through to normal logic
119	            } else {
120	                // Still not ready — keep systems_down
121	                return null;
122	            }
123	        }
124	
125	        $newStatusValue = $computed->value;
126	
127	        if ($currentStatusValue === $newStatusValue) {
128	            return null;
129	        }
130	
