13	    public function create(
14	        string $shopDomain,
15	        string $accessToken,
16	        array $shopData,
17	        array $scopes,
18	        string $shopEmail,
19	    ): string {
20	        $token = bin2hex(random_bytes(32));
21	
22	        Cache::put(self::CACHE_PREFIX.$token, [
23	            'shop_domain' => $shopDomain,
24	            'access_token' => encrypt($accessToken),
25	            'shop_data' => $shopData,
26	            'scopes' => $scopes,
27	            'shop_email' => $shopEmail,
28	            'created_at' => now()->toIso8601String(),
29	        ], now()->addMinutes(self::TTL_MINUTES));
30	
31	        return $token;
32	    }
33	
34	    public function peek(string $token): ?array
35	    {
36	        $token = trim($token);
37	        if ($token === '') {
38	            return null;
39	        }
40	
41	        $data = Cache::get(self::CACHE_PREFIX.$token);
42	        if (! is_array($data)) {
43	            return null;
44	        }
45	
46	        return $this->decryptPayload($data);
47	    }
48	
49	    public function consume(string $token): ?array
50	    {
51	        $token = trim($token);
52	        if ($token === '') {
53	            return null;
54	        }
55	
56	        $data = Cache::pull(self::CACHE_PREFIX.$token);
57	        if (! is_array($data)) {
58	            return null;
59	        }
60	
61	        return $this->decryptPayload($data);
62	    }
