15	{
16	    public function getAccessToken(Professional $professional): string
17	    {
18	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
19	        if (! $integration) {
20	            throw new SquareApiException('Square access token is missing.');
21	        }
22	
23	        $token = trim((string) ($integration->access_token ?? ''));
24	        if ($token === '') {
25	            throw new SquareApiException('Square access token is missing.');
26	        }
27	
28	        $expiresAt = $integration->expires_at;
29	        if ($expiresAt && $expiresAt->greaterThan(now()->addMinutes(5))) {
30	            return $token;
31	        }
