36	    public function refreshAccessToken(Professional $professional): string
37	    {
38	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
39	        if (! $integration) {
40	            throw new SquareApiException('Square refresh token is missing.');
41	        }
42	
43	        // Single-flight lock: only one concurrent caller performs the HTTP refresh.
44	        // Others wait up to 10s, then re-read the row (which should now be fresh).
45	        $lock = Cache::lock('integration_refresh:'.$integration->id, 30);
46	
47	        try {
48	            $lock->block(10);
49	        } catch (LockTimeoutException $e) {
50	            // Timed out waiting for the lock — re-read and return if another process already refreshed.
51	            $integration->refresh();
52	            $expiresAt = $integration->expires_at;
53	            if ($expiresAt && $expiresAt->greaterThan(now()->addMinutes(5))) {
54	                $token = trim((string) ($integration->access_token ?? ''));
55	                if ($token !== '') {
56	                    return $token;
57	                }
58	            }
59	            throw $e;
60	        }
61	
62	        try {
63	            // Double-check after acquiring the lock: a concurrent caller may have just refreshed.
64	            $integration->refresh();
65	            $expiresAt = $integration->expires_at;
66	            if ($expiresAt && $expiresAt->greaterThan(now()->addMinutes(5))) {
67	                $token = trim((string) ($integration->access_token ?? ''));
68	                if ($token !== '') {
69	                    return $token;
70	                }
71	            }
72	
73	            $refreshToken = trim((string) ($integration->refresh_token ?? ''));
74	            if ($refreshToken === '') {
75	                throw new SquareApiException('Square refresh token is missing.');
76	            }
77	
78	            $clientId = trim((string) config('services.square.application_id', ''));
79	            $clientSecret = trim((string) config('services.square.client_secret', ''));
80	
81	            if ($clientId === '' || $clientSecret === '') {
82	                throw new SquareApiException('Square OAuth credentials are not configured.');
83	            }
84	
85	            $response = Http::acceptJson()
86	                ->asJson()
87	                ->timeout(20)
88	                ->post($this->baseUrl().'/oauth2/token', [
89	                    'client_id' => $clientId,
90	                    'client_secret' => $clientSecret,
91	                    'grant_type' => 'refresh_token',
92	                    'refresh_token' => $refreshToken,
93	                ]);
94	
95	            $payload = $response->json();
96	            if (! $response->successful() || ! is_array($payload)) {
97	                throw new SquareApiException(
98	                    sprintf('Failed to refresh Square token (HTTP %s).', $response->status()),
99	                    $response->status(),
100	                    is_array($payload) ? $payload : null
101	                );
102	            }
103	
104	            $accessToken = trim((string) ($payload['access_token'] ?? ''));
105	            if ($accessToken === '') {
106	                throw new SquareApiException('Square token refresh response did not include access_token.');
107	            }
108	
109	            $integration->access_token = $accessToken;
110	            $integration->refresh_token = $payload['refresh_token'] ?? $integration->refresh_token;
111	            $integration->expires_at = isset($payload['expires_at'])
112	                ? CarbonImmutable::parse((string) $payload['expires_at'])
113	                : null;
114	            $integration->save();
115	
116	            return $accessToken;
117	        } finally {
118	            try {
119	                $lock->release();
120	            } catch (Throwable) {
121	                // Lock already expired or driver doesn't support release; ignore.
122	            }
123	        }
124	    }
