126	    /**
127	     * Revoke the access token at Square. Callers catch and log — deletion must not be blocked.
128	     * Square revoke requires "Authorization: Client {secret}" rather than a bearer token.
129	     */
130	    public function revokeToken(ProfessionalIntegration $integration): void
131	    {
132	        $clientId = trim((string) config('services.square.application_id', ''));
133	        $clientSecret = trim((string) config('services.square.client_secret', ''));
134	        $accessToken = trim((string) ($integration->access_token ?? ''));
135	
136	        if ($clientId === '' || $clientSecret === '' || $accessToken === '') {
137	            return;
138	        }
139	
140	        Http::acceptJson()
141	            ->asJson()
142	            ->timeout(10)
143	            ->withHeaders(['Authorization' => 'Client '.$clientSecret])
144	            ->post($this->baseUrl().'/oauth2/revoke', [
145	                'client_id' => $clientId,
146	                'access_token' => $accessToken,
147	            ]);
148	    }
149	
150	    private function baseUrl(): string
151	    {
152	        $environment = strtolower((string) config('services.square.environment', 'production'));
153	        if ($environment === 'sandbox') {
154	            return 'https://connect.squareupsandbox.com';
155	        }
156	
157	        return 'https://connect.squareup.com';
158	    }
