3	namespace App\Http\Controllers\Api;
4	
5	use App\Listeners\RecordScheduledTaskHeartbeat;
6	use Cron\CronExpression;
7	use Illuminate\Console\Scheduling\Schedule;
8	use Illuminate\Http\JsonResponse;
9	use Illuminate\Support\Carbon;
10	use Illuminate\Support\Facades\Cache;
11	use Illuminate\Support\Facades\DB;
12	use Throwable;
13	
14	// V2: Liveness/readiness probe. Checks database and Redis connectivity with response times for deployment health checks.
15	class HealthController extends ApiController
16	{
17	    public function check(): JsonResponse
18	    {
19	        $db = $this->checkDatabase();
20	        $cache = $this->checkCache();
21	
22	        $status = [
23	            'app' => 'healthy',
24	            'database' => $db,
25	            'cache' => $cache,
26	        ];
27	
28	        $allHealthy = ($db['status'] === 'healthy') && ($cache['status'] === 'healthy');
29	
30	        return $this->success($status, $allHealthy ? 200 : 503);
31	    }
32	
33	    // Scheduler heartbeat check. Returns 503 if any task hasn't reported a
34	    // "task starting" event within 2× its cron interval (min 1h buffer).
35	    // Catches a stopped Laravel Cloud cron runner — onFailure() can't, since
36	    // it only fires when a task actually runs.
37	    public function scheduler(): JsonResponse
38	    {
39	        $schedule = app(Schedule::class);
40	        $now = now();
41	        $tasks = [];
42	        $healthy = true;
43	
44	        foreach ($schedule->events() as $event) {
45	            $name = RecordScheduledTaskHeartbeat::taskKey($event);
46	            $lastRunIso = Cache::get(RecordScheduledTaskHeartbeat::CACHE_PREFIX.$name);
47	            $lastRun = $lastRunIso ? Carbon::parse($lastRunIso) : null;
48	
49	            // Max acceptable staleness: 2× cron interval, floored at 1h. The floor
50	            // covers hourly tasks right after deploy when cache is cold.
51	            $cron = new CronExpression($event->expression);
52	            $prev = $cron->getPreviousRunDate($now);
53	            $prevPrev = $cron->getPreviousRunDate($prev);
54	            $intervalSeconds = $prev->getTimestamp() - $prevPrev->getTimestamp();
55	            $maxAgeSeconds = max($intervalSeconds * 2, 3600);
56	
57	            $ageSeconds = $lastRun ? $now->getTimestamp() - $lastRun->getTimestamp() : null;
58	            $stale = $ageSeconds === null || $ageSeconds > $maxAgeSeconds;
59	            if ($stale) {
60	                $healthy = false;
61	            }
62	
63	            $tasks[] = [
64	                'name' => $name,
65	                'expression' => $event->expression,
66	                'last_run_at' => $lastRunIso,
67	                'age_seconds' => $ageSeconds,
68	                'max_age_seconds' => $maxAgeSeconds,
69	                'stale' => $stale,
70	            ];
71	        }
72	
73	        return $this->success(['healthy' => $healthy, 'tasks' => $tasks], $healthy ? 200 : 503);
74	    }
75	
76	    private function checkDatabase(): array
77	    {
78	        $start = microtime(true);
79	
80	        try {
81	            DB::connection()->getPdo();
82	            $ms = (microtime(true) - $start) * 1000;
83	
84	            return ['status' => 'healthy', 'ms' => $ms];
85	        } catch (Throwable $e) {
86	            $ms = (microtime(true) - $start) * 1000;
87	
88	            return [
89	                'status' => 'unhealthy',
90	                'ms' => $ms,
91	                'error' => $e->getMessage(),
92	            ];
93	        }
94	    }
95	
96	    private function checkCache(): array
97	    {
98	        $start = microtime(true);
99	
100	        try {
101	            $store = config('cache.default'); // or config('cache.default') depending on your config
102	            $key = 'health:cache:'.bin2hex(random_bytes(8));
103	            $value = bin2hex(random_bytes(8));
104	
105	            Cache::put($key, $value, now()->addSeconds(10));
106	            $read = Cache::get($key);
107	            Cache::forget($key);
108	
109	            $ms = (microtime(true) - $start) * 1000;
